package net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRule;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueobject.PatternVO;

@RequiredArgsConstructor
public class PatternValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<PatternVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getPattern() {
    return value.map(PatternVO::getPattern);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<PatternVO> getPatternValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param pattern
   * @return
   */
  public T pattern(PatternVO pattern) {
    this.value = Optional.of(pattern);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param pattern
   * @return
   */
  public T pattern(Optional<PatternVO> pattern) {
    this.value = pattern;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param pattern
   * @return
   */
  public T pattern(String pattern) {
    this.value = Optional.of(PatternVO.from(pattern));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public PatternVO readPattern(final Optional<ObservedFingerprintRule> original,
      final ConstraintFailList fails) {
    PatternVO result =
        value.orElse(original.map(ObservedFingerprintRule::getPatternValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "pattern", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetPattern() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetPatternIfMatches(final String field) {
    if ("pattern".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
